import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const MAP = { NL:10, TAB:9, CR:13, FF:12, VT:11, NBSP:160, BOM:0xFEFF, NUL:0, SP:32,
  ENDASH:0x2013, EMOJI:0x1F600, ZWSP:0x200B, LS:0x2028, PS:0x2029, U0085:0x85, U001C:0x1C, ESC:0x1B, DEL:0x7F, SHY:0xAD, IDEOSP:0x3000 };
export function dec(s) {
  return s.replace(/<([A-Z0-9_]+)(?:\*(\d+))?>/g, (m, name, n) => {
    if (!(name in MAP)) throw new Error('bad token ' + name);
    return String.fromCodePoint(MAP[name]).repeat(n ? +n : 1);
  });
}
const lines = readFileSync(process.argv[2], 'utf8').split('\n').filter(l => l.trim() && !l.startsWith('#'));
for (const line of lines) {
  const [label, ...rawArgv] = JSON.parse(line);
  const argv = rawArgv.map(dec);
  let r;
  try { r = spawnSync('/workspace/dataset/test6_executable', argv, { encoding: 'utf8', maxBuffer: 1 << 28 }); }
  catch (e) { console.log('### ' + label); console.log('SPAWN-THROW ' + e.code + ' ' + e.message); continue; }
  console.log('### ' + label);
  console.log('ARGV ' + JSON.stringify(argv));
  console.log('RC   ' + r.status + (r.signal ? ' SIG ' + r.signal : ''));
  console.log('OUT  ' + JSON.stringify(r.stdout));
  console.log('ERR  ' + JSON.stringify(r.stderr));
}
XEOF
