// Generates /workspace/harness/cases/10-argparse-cli.jsonl
// Every case is a value that argparse ACCEPTS as the argument to --a
// (i.e. it never triggers RC 2), so the harness can run it.
import { writeFileSync } from 'node:fs';

const C = {
  NL: '\n', TAB: '\t', CR: '\r', FF: '\f', VT: '', SP: ' ',
  NBSP: ' ', BOM: '﻿', ZWSP: '​', LS: ' ', PS: ' ',
  NEL: '', FS: '', ESC: '', DEL: '', SHY: '­',
  IDEOSP: '　', EMOJI: '\u{1F600}', ENDASH: '–', EMDASH: '—',
  MINUS: '−', FULLDASH: '－', SURR: '\ud83d',
};
const cases = [];
const add = (label, text) => cases.push({ label, text });

// --- 1. empty / whitespace-only values (argparse accepts, markdown yields "") ---
add('empty-string', '');
add('single-space', C.SP);
add('five-spaces', C.SP.repeat(5));
add('single-tab', C.TAB);
add('single-nl', C.NL);
add('three-nl', C.NL.repeat(3));
add('single-cr', C.CR);
add('crlf-only', C.CR + C.NL);
add('single-ff', C.FF);
add('single-vt', C.VT);
add('space-nl-space', C.SP + C.NL + C.SP);
add('tab-nl', C.TAB + C.NL);
add('nl-tab-nl', C.NL + C.TAB + C.NL);
add('spaces-tabs-mixed', C.SP + C.TAB + C.SP + C.TAB);
add('nbsp-only', C.NBSP);
add('ideographic-space-only', C.IDEOSP);
add('zwsp-only', C.ZWSP);
add('bom-only', C.BOM);
add('ls-only', C.LS);
add('ps-only', C.PS);
add('nel-only', C.NEL);
add('shy-only', C.SHY);

// --- 2. line-ending normalisation ---
add('lf-two-lines', 'l1' + C.NL + 'l2');
add('crlf-two-lines', 'a' + C.CR + C.NL + 'b');
add('cr-two-lines', 'a' + C.CR + 'b');
add('cr-cr-blank', 'a' + C.CR + C.CR + 'b');
add('crlf-crlf-blank', 'a' + C.CR + C.NL + C.CR + C.NL + 'b');
add('mixed-eol', 'a' + C.CR + C.NL + 'b' + C.CR + 'c' + C.NL + 'd');
add('trailing-lf', 'x' + C.NL);
add('trailing-crlf', 'x' + C.CR + C.NL);
add('trailing-cr', 'x' + C.CR);
add('trailing-two-lf', 'x' + C.NL + C.NL);
add('trailing-three-lf', 'x' + C.NL + C.NL + C.NL);
add('leading-lf', C.NL + 'x');
add('leading-two-lf', C.NL + C.NL + 'x');
add('leading-crlf', C.CR + C.NL + 'x');
add('lf-then-spaces', 'x' + C.NL + C.SP + C.SP);
add('spaces-then-lf-x', C.SP + C.SP + C.NL + 'x');

// --- 3. tabs / control chars inside text (byte pass-through) ---
add('tab-inside', 'a' + C.TAB + 'b');
add('tab-at-start', C.TAB + 'a');
add('two-tabs-inside', 'a' + C.TAB + C.TAB + 'b');
add('ff-inside', 'a' + C.FF + 'b');
add('vt-inside', 'a' + C.VT + 'b');
add('fs-inside', 'a' + C.FS + 'b');
add('esc-inside', 'a' + C.ESC + 'b');
add('del-inside', 'a' + C.DEL + 'b');
add('nel-inside', 'a' + C.NEL + 'b');
add('ls-inside', 'a' + C.LS + 'b');
add('ps-inside', 'a' + C.PS + 'b');
add('nbsp-inside', 'a' + C.NBSP + 'b');
add('shy-inside', 'a' + C.SHY + 'b');
add('zwsp-inside', 'a' + C.ZWSP + 'b');
add('ideospace-inside', 'a' + C.IDEOSP + 'b');
add('bom-leading', C.BOM + 'x');
add('bom-mid', 'a' + C.BOM + 'b');
add('lone-surrogate-not-possible-substitute', 'a' + C.EMOJI + 'b');

// --- 4. unicode / emoji pass-through ---
add('cjk', '你好');
add('cjk-heading', '# 中文标题');
add('emoji-para', C.EMOJI + ' hi');
add('emoji-only', C.EMOJI);
add('emoji-pair', C.EMOJI + C.EMOJI);
add('accented', 'café naïve');
add('combining', 'é');
add('rtl', 'שלום');
add('endash-lead', C.ENDASH + 'x');
add('emdash-lead', C.EMDASH + 'x');
add('minus-sign-lead', C.MINUS + '1');
add('fullwidth-dash-lead', C.FULLDASH + 'a');
add('endash-hr-lookalike', C.ENDASH.repeat(3));

// --- 5. values that START with '-' but argparse still accepts ---
add('lone-dash', '-');
add('neg-int', '-1');
add('neg-int-long', '-12345');
add('neg-float-leading-dot', '-.5');
add('neg-float', '-0.0');
add('neg-float-padded', '-00.50');
add('dash-space-x-bullet', '- x');
add('dash-space-x-y', '- x y');
add('dash-x-space-y', '-x y');
add('dash-then-space-only', '-' + C.SP);
add('dashdash-then-space', '--' + C.SP);
add('space-then-dashdash', C.SP + '--');
add('space-then-dashes', C.SP + '---');
add('dash-tab-inside-with-space', '- a' + C.TAB + 'b');
add('dashes-with-space', '--- x');
add('bullet-list-two', '- a' + C.NL + '- b');
add('hr-after-space', C.SP + C.SP + C.SP + '---');
add('setext-with-space-first', ' a' + C.NL + '---');
add('plus-one', '+1');
add('plus-bullet', '+ x');
add('at-sign-value', '@/tmp/nope.txt');
add('slash-value', '/a');
add('equals-lead', '=x');
add('equals-only', '=');
add('eq-eq', '==');

// --- 6. values containing '=' (relevant to --a=VALUE splitting) ---
add('has-equals', 'x=y');
add('has-two-equals', 'x=y=z');
